    [2587] = { name = "Rune of Atonement", quality = 5, entry = 1891, desc = "Your spell and physical damage is reduced by 75% and the single target spell damage you deal heals you and your most damaged nearby ally within 40 yards of the target or the caster." },
    [2588] = { name = "Rune of Haunting Reverberations", quality = 5, entry = 1892, desc = "Your Haunt will now re-apply to a random target after the duration has ended. This reverberating Haunt will apply or refresh your shadow damaging over time effects on the target." },
    [2592] = { name = "Rune of the Icy Winds of Northrend", quality = 5, entry = 1893, desc = "The Icy Winds of Northrend heed your call. When you cast Howling Blast, a raging Blizzard descends upon your primary target." },
    [2593] = { name = "Rune of the Thunderous Gale", quality = 5, entry = 1894, desc = "Your Thunder Clap gathers the winds into a raging Thunderous Gale, lashing nearby foes with stormy wrath that scales with your Thunder Clap's damage." },
    [2594] = { name = "Rune of Deepening Frost", quality = 5, entry = 1895, desc = "Each Icy Touch leaves your foe more vulnerable to the cold, building Permafrost stacks that increases the Frost damage you deal to them up. Stacks up to 3 times." },
