    [2613] = { name = "Rune of the Shocking Rush of the Inferno", quality = 5, entry = 1901, desc = "Your Flame Shock now triggers a shocking Inferno Rush of haste increasing your Spell Casting Speed by 30%. The overload of this inferno causes the cooldown of your Flame Shock to triple." },
    [2614] = { name = "Rune of Blood Magic", quality = 5, entry = 1902, desc = "Your Life Tap now grants you insight into the ancient rites of Blood Magic. So long as you know Life Tap, your spells are fueled by your own blood rather than Mana, requiring twice the usual cost in Health." },
    [2615] = { name = "Rune of the Thousandfold Frost", quality = 5, entry = 1903, desc = "Your Frostbolt spell now splinters a thousandfold launching a volley of Frost in front of you at every enemy target. Your Frostbolt spell now has a 30 sec. cooldown." },
    [2616] = { name = "Rune of the Sanguine Blight", quality = 5, entry = 1904, desc = "Your Blood Boil now deals additional damage to targets afflicted with your Priest and Warlock Shadow damaging overtime effects and refreshes them." },
    [2617] = { name = "Rune of the Raptor Loa's Fury", quality = 5, entry = 1905, desc = "Your Raptor Strike invokes the fury of the Raptor Loa, summoning feral spirit raptors to fight at your side for 15 sec and increasing its damage by 200%. Its cooldown is increased by 30 sec." },
    [2618] = { name = "Rune of the Eternal Conduit", quality = 5, entry = 1906, desc = "Your Lightning Shield turns you into a living conduit for the elements, your shield continuously discharges lightning into 1 random nearby enemy every 3 seconds and no longer loses charges on hit and is eternal." },
    [2619] = { name = "Rune of the Flourishing Surging Wave", quality = 5, entry = 1907, desc = "Your Healing Wave critical strikes grant a Surging Wave, reducing the cast time and global cooldown of Healing Wave. Healing Wave also causes your healing over time effects to bloom anew, adding its base cast time to their duration on the target, up to their maximum duration." },
    [2620] = { name = "Rune of the Archangel", quality = 5, entry = 1908, desc = "You gain the Evangelism and Archangel abilities. Smite and Holy Fire build Evangelism, empowering your holy magic. Archangel may be invoked to consume your Evangelism, restoring mana and greatly increasing your healing done." },
    [2621] = { name = "Rune of the Righteous Crusading Storm", quality = 5, entry = 1909, desc = "Your Divine Storm now carries the zeal of a crusade, delivering a Crusader Strike to each enemy it strikes." },
    [2622] = { name = "Rune of the Vortex of Imbued Blades", quality = 5, entry = 1910, desc = "Your Bladestorm lasts twice as long and is transformed into a vortex of enchanted steel. Your imbued blades cast magical afflictions onto enemies struck by your wizard oiled blades, randomly applying your damaging spell over time effects to the target." },
    [2624] = { name = "Rune of Elemental Unleashing", quality = 5, entry = 2642, desc = "Your weapon enchantments answer your call, granting you the ability to cast Unleash Elements." },
    [2625] = { name = "Rune of the Ancient King", quality = 5, entry = 2643, desc = "While Righteous Fury is active, grants the ability to summon the Guardian of Ancient Kings for 12 sec. The Guardian protects you, reducing all damage you take by 50%." },
    [2627] = { name = "Rune of the Falling Stars", quality = 5, entry = 2644, desc = "Teaches Starsurge and Shooting Stars." },
    [2628] = { name = "Rune of the Enchanted Quiver", quality = 5, entry = 2645, desc = "Your mastery of both bow and spell allows your enchanted arrows to carry traces of your magical power." },
    [2631] = { name = "Rune of Encircling Frost", quality = 5, entry = 2646, desc = "Your Frost Nova now conjures a Ring of Frost at your location, taking 3 sec to coalesce. Enemies entering the fully formed ring become frozen for 10 sec. The ring lasts 12 sec." },
    [2632] = { name = "Rune of the Blindsiding Blade", quality = 5, entry = 2647, desc = "You can now step through the shadows before your enemy can react, revealing their blind side to your blade. Backstab may now be used regardless of your foe's facing." },
    [2635] = { name = "Rune of Cenarius' Gate", quality = 5, entry = 2648, desc = "The Emerald Dream guides your path to those most in need. Teleport: Moonglade is now Cenarius' Gate, allowing you to instantly traverse to the side of the nearest most injured ally within 60 yards." },
    [2638] = { name = "Rune of the Druids of the Flame", quality = 5, entry = 2649, desc = "Walk the scorched path of the Druids of the Flame. Assume the form of the Firecat, moving with blazing swiftness as your claws ignite your foes." },
    [2640] = { name = "Rune of the Overgrowth", quality = 5, entry = 2650, desc = "Nature answers abundance with abundance. Your Rejuvenation no longer replaces your existing Rejuvenation and can stack up to 3 times on a single target." },
    [2642] = { name = "Rune of the Hallowed Path", quality = 5, entry = 2651, desc = "Consecration now infuses you with the Light, continually sanctifying the ground beneath your feet for its duration." },
    [5223] = { name = "Rune of Divine Blessings", quality = 5, entry = 2652, desc = "Your holy or nature healing spells may stir with renewed power, calling forth an additional blessing upon you or your allies." },
    [5239] = { name = "Rune of the Benevolent Crusader", quality = 5, entry = 2653, desc = "Your direct Holy spells healing that do not overheal fills you with benevolence, granting a stack of Benevolent Crusader." },
    [5243] = { name = "Rune of Ever-Changing Assault", quality = 5, entry = 2654, desc = "Weaving different direct damage Physical abilities into your assault builds Assault Momentum, increasing your Physical damage by 4% with each stack, up to 6 stacks. Casting any non-physical damage spell breaks your momentum and resets all stacks." },
    [5247] = { name = "Rune of the Keepers of the Grove", quality = 5, entry = 2655, desc = "Your Treants abandon their attacks to instead tend to wounded allies, invoking the restorative powers of nature in their defense. They can cast any Druid healing spell you have learned, except Tranquility, and will not heal you while you remain above 90% health." },
    [5269] = { name = "Rune of the Firebrand", quality = 5, entry = 2656, desc = "Your melee abilities strike with searing heat, dealing additional Fire damage and inflicting a Searing Brand upon your target." },
    [5273] = { name = "Rune of the Devout Flames", quality = 5, entry = 2657, desc = "Your non-periodic Fire damage is increased by 1% for each charge of Inner Fire, but the number of charges granted by Inner Fire is reduced by 50%. Dealing non-periodic Fire damage consumes a charge of Inner Fire." },
    [5290] = { name = "Rune of Near Endless Time", quality = 5, entry = 2658, desc = "Your Borrowed Time now also increases the critical strike chance of your direct healing spells by 20%. No longer fleeting, Borrowed Time is no longer consumed by casting spells." },
    [5295] = { name = "Rune of the Frozen Tempest", quality = 5, entry = 2659, desc = "Your direct Nature and Frost damage stirs the elements, granting a stack of Gathering Tempest. At 20 stacks, the storm erupts upon your target as a Frozen Tempest, dealing Froststorm damage over 8 seconds and while in the Eye of the Frozen Tempest your spell casting speed is increased by 10% for 8 seconds." },
    [5304] = { name = "Rune of the Plague Beast", quality = 5, entry = 2670, desc = "Teaches you Festering Maul, usable only in Bear Form." },
    [5334] = { name = "Rune of the Trusted Shield", quality = 5, entry = 2671, desc = "Teaches you Trusted Shield, allowing you to channel a powerful defensive stance for up to 10 sec. While channeling, all successful blocks are critical blocks, your movement speed is reduced by 50%, and you periodically Shield Slam all nearby enemies. Requires a shield." },
    [5332] = { name = "Rune of the Explosive Impact", quality = 5, entry = 2672, desc = "Teaches you Explosive Shot (Impact), allowing you to mark a chosen ground with deadly precision before unleashing a devastating explosive charge upon it, afflicting all enemies caught within the blast. This ability shares a cooldown with Explosive Shot and related abilities." },
    [5311] = { name = "Rune of the Rolling Waves", quality = 5, entry = 2673, desc = "The restorative tides gather around those touched by your Riptide, increasing the critical healing chance of your Nature healing spells against them by 20%. When Healing Wave critically heals, it sends the tide rolling onward, spreading Riptide to another nearby ally. Additionally, Riptide's healing over time can now critically heal." },
    [5344] = { name = "Rune of the Blades of Sun and Moon", quality = 5, entry = 2674, desc = "Teaches you Astral Strike, an empowered Sinister Strike that calls upon the celestial forces of sun and moon, dealing Spellstorm damage in addition to 50% of your normal weapon damage and granting a stack of Knight of the Eclipse." },
    [5340] = { name = "Rune of the Lightforged Champion", quality = 5, entry = 2675, desc = "Surrender your mortal strength to the Light. Your Physical damage dealt is reduced by 50%, but your Holy spell damage is increased by 30% of your Strength. Crusader Strike and Divine Storm now strike with Holy damage and scale with your Holy spell damage." },
