    [4751] = { name = "Rune of Mind Mastery", quality = 4, entry = 2270, desc = "Increases spell power by 9% of your total Intellect." },
    [4752] = { name = "Rune of Playing with Fire", quality = 4, entry = 2271, desc = "Increases all spell damage caused by 2% and all spell damage taken by 2%." },
    [4753] = { name = "Rune of Blazing Speed", quality = 4, entry = 2272, desc = "Gives you a 10% chance when hit by a melee or ranged attack to increase your movement speed by 50% and dispel all movement impairing effects.  This effect lasts 8 sec." },
    [4754] = { name = "Rune of Empowered Fire", quality = 4, entry = 2273, desc = "Increases the damage of your Fireball, Frostfire Bolt and Pyroblast spells by an amount equal to 20% of your spell power.  In addition, each time your Ignite talent causes damage, you have a 100% chance to regain 2% of your base mana." },
    [4755] = { name = "Rune of Frozen Core", quality = 4, entry = 2274, desc = "Reduces the damage taken from all spells by 6%." },
    [4756] = { name = "Rune of Arctic Winds", quality = 4, entry = 2275, desc = "Increases all Frost damage you cause by 5% and reduces the chance melee and ranged attacks will hit you by 5%." },
    [4757] = { name = "Rune of Molten Fury", quality = 4, entry = 2276, desc = "Increases damage of all spells against targets with less than 35% health by 12%." },
    [4758] = { name = "Rune of Empowered Frostbolt", quality = 4, entry = 2277, desc = "Increases the damage of your Frostbolt spell by an amount equal to 10% of your spell power and reduces the cast time by 0.2.1 sec." },
    [4759] = { name = "Rune of Pure of Heart", quality = 4, entry = 2278, desc = "Reduces the duration of Curse, Disease and Poison effects by 30%." },
    [4760] = { name = "Rune of Purifying Power", quality = 4, entry = 2279, desc = "Reduces the mana cost of your Cleanse, Purify and Consecration spells by 10% and reduces the cooldown of your Exorcism and Holy Wrath spells by 33%." },
    [4761] = { name = "Rune of Blessed Life", quality = 4, entry = 2280, desc = "All attacks against you have a 10% chance to cause half damage." },
    [4762] = { name = "Rune of Light's Grace", quality = 4, entry = 2281, desc = "Gives your Holy Light spell a 100% chance to reduce the cast time of your next Holy Light spell by 0.5 sec.  This effect lasts 15 sec." },
    [4763] = { name = "Rune of Holy Guidance", quality = 4, entry = 2282, desc = "Increases your spell power by 12% of your total Intellect." },
    [4764] = { name = "Rune of Sacred Duty", quality = 4, entry = 2283, desc = "Increases your total Stamina by 4%, reduces the cooldown of your Divine Shield and Divine Protection spells by 60 sec." },
    [4765] = { name = "Rune of Ardent Defender", quality = 4, entry = 2284, desc = "Damage that takes you below 35% health is reduced by 6%.  In addition, attacks which would otherwise kill you cause you to be healed by up to 30% of your maximum health (amount healed based on defense).  This healing effect cannot occur more often than once every 2 min." },
    [4766] = { name = "Rune of Combat Expertise", quality = 4, entry = 2285, desc = "Increases your expertise by 6, total Stamina and chance to critically hit by 6%." },
    [4767] = { name = "Rune of Crusade", quality = 4, entry = 2286, desc = "Increases all damage caused by 3% and all damage caused against Humanoids, Demons, Undead and Elementals by an additional 3%." },
    [4768] = { name = "Rune of Sanctified Retribution", quality = 4, entry = 2287, desc = "Increases the damage caused by Retribution Aura by 50% and all damage caused by friendly targets affected by any of your Auras is increased by 3%." },
    [4769] = { name = "Rune of Divine Purpose", quality = 4, entry = 2288, desc = "Reduces your chance to be hit by spells and ranged attacks by 4% and gives your Hand of Freedom spell a 100% chance to remove any Stun effects on the target." },
    [4770] = { name = "Rune of Judgements of the Wise", quality = 4, entry = 2289, desc = "Your damaging Judgement spells have a 100% chance to grant the Replenishment effect to up to 10 party or raid members mana regeneration equal to 1% of their maximum mana per 5 sec for 15 sec, and to immediately grant you 15% of your base mana." },
    [4771] = { name = "Rune of Fanaticism", quality = 4, entry = 2290, desc = "Increases the critical strike chance of all Judgements capable of a critical hit by 18% and reduces threat caused by all actions by 30% except when under the effects of Righteous Fury." },
    [4772] = { name = "Rune of Empowered Corruption", quality = 4, entry = 2291, desc = "Increases the damage of your Corruption spell by an amount equal to 36% of your spell power." },
    [4773] = { name = "Rune of Shadow Embrace", quality = 4, entry = 2292, desc = "Your Shadow Bolt and Haunt spells apply the Shadow Embrace effect, increasing all shadow periodic damage dealt to the target by you by 5%, and reduces all periodic healing done to the target by 10%. Lasts for 12 sec. Stacks up to 3 times." },
    [4774] = { name = "Rune of Malediction", quality = 4, entry = 2293, desc = "Increases your spell damage by 3%, and increases the periodic critical strike chance of your Corruption and Unstable Affliction spells by 9%." },
    [4775] = { name = "Rune of Surprise Attacks", quality = 4, entry = 2294, desc = "Your finishing moves can no longer be dodged, and the damage dealt by your Sinister Strike, Backstab, Shiv, Hemorrhage and Gouge abilities is increased by 6%." },
    [4776] = { name = "Rune of Blessed Resilience", quality = 4, entry = 2295, desc = "Increases the effectiveness of your healing spells by 3%, and critical hits made against you have a 60% chance to prevent you from being critically hit again for 6 sec." },
    [4777] = { name = "Rune of Surge of Light", quality = 4, entry = 2296, desc = "Your spell criticals have a 50% chance to cause your next Smite or Flash Heal spell to be instant cast, cost no mana but be incapable of a critical hit.  This effect lasts 10 sec." },
    [4778] = { name = "Rune of Empowered Healing", quality = 4, entry = 2297, desc = "Your Greater Heal spell gains an additional 25% and your Flash Heal and Binding Heal gain an additional 25% of your bonus healing effects." },
    [4779] = { name = "Rune of Absolution", quality = 4, entry = 2298, desc = "Reduces the mana cost of your Dispel Magic, Cure Disease, Abolish Disease and Mass Dispel spells by 30%." },
    [4780] = { name = "Rune of Focused Power", quality = 4, entry = 2299, desc = "Increases damage and healing done by your spells by 2%. In addition, your Mass Dispel cast time is reduced by 0.6 sec." },
    [4781] = { name = "Rune of Misery", quality = 4, entry = 2300, desc = "Your Shadow Word: Pain, Mind Flay and Vampiric Touch spells also increase the chance for harmful spells to hit by 3% lasting 24 sec, and increases the benefit from spell power gained by your Mind Blast, Mind Flay and Mind Sear spells by 15%." },
    [4782] = { name = "Rune of Reflective Shield", quality = 4, entry = 2301, desc = "Causes 40% of the damage you absorb with Power Word: Shield to reflect back at the attacker.  This damage causes no threat." },
    [4784] = { name = "Rune of Focused Mind", quality = 4, entry = 2302, desc = "Reduces the mana cost of your Mind Blast, Mind Control, Mind Flay and Mind Sear spells by 15%." },
    [4786] = { name = "Rune of Shadow Power", quality = 4, entry = 2303, desc = "Increases the critical strike damage bonus of your Mind Blast, Mind Flay, and Shadow Word: Death spells by 100%." },
    [4787] = { name = "Rune of Mind Melt", quality = 4, entry = 2304, desc = "Increases the critical strike chance of your Mind Blast, Mind Flay and Mind Sear spells by 4%, and increases the periodic critical strike chance of your Vampiric Touch, Devouring Plague and Shadow Word: Pain spells by 6%." },
    [4788] = { name = "Rune of Lunar Guidance", quality = 4, entry = 2305, desc = "Increases your spell power by 12% of your total Intellect." },
    [4789] = { name = "Rune of Balance of Power", quality = 4, entry = 2306, desc = "Increases your chance to hit with all spells by 2% and reduces your damage taken from all spells by 6%." },
    [4790] = { name = "Rune of Improved Faerie Fire", quality = 4, entry = 2307, desc = "Your Faerie Fire spell also increases the chance the target will be hit by spell attacks by 3%, and increases the critical strike chance of your damage spells by 6% on targets afflicted by Faerie Fire." },
    [4791] = { name = "Rune of Wrath of Cenarius", quality = 4, entry = 2308, desc = "Your Starfire spell gains an additional 20% and your Wrath gains an additional 10% of your bonus damage effects." },
    [4792] = { name = "Rune of Spiritual Attunement", quality = 4, entry = 2309, desc = "A passive ability that gives the Paladin mana when healed by other friendly targets' spells.  The amount of mana gained is equal to 10% of the amount healed." },
    [4794] = { name = "Rune of Survival of the Fittest", quality = 4, entry = 2310, desc = "Increases all attributes by 6%, reduces the chance you'll be critically hit by melee attacks by 6%, and increases your armor contribution from cloth and leather items in Bear Form and Dire Bear Form by 33%." },
    [4795] = { name = "Rune of Predatory Instincts", quality = 4, entry = 2311, desc = "While in Cat Form increases your damage from melee critical strikes by 15% and reduces the damage taken from area of effect attacks by 10%." },
    [4796] = { name = "Rune of Nurturing Instinct", quality = 4, entry = 2312, desc = "Increases your healing spells by up to 70% of your Agility, and increases healing done to you by 10% while in Cat form." },
    [4797] = { name = "Rune of Empowered Touch", quality = 4, entry = 2313, desc = "Your Healing Touch spell gains an additional 25% and your Nourish spell gains an additional 20% of your bonus healing effects." },
    [4798] = { name = "Rune of Natural Perfection", quality = 4, entry = 2314, desc = "Your critical strike chance with all spells is increased by 3% and critical strikes against you give you the Natural Perfection effect reducing all damage taken by 4%.  Stacks up to 3 times.  Lasts 8 sec." },
    [4799] = { name = "Rune of Empowered Rejuvenation", quality = 4, entry = 2315, desc = "The bonus healing effects of your healing over time spells is increased by 20%." },
    [4800] = { name = "Rune of Dreamstate", quality = 4, entry = 2316, desc = "Regenerate mana equal to 10% of your Intellect every 5 sec, even while casting." },
    [4802] = { name = "Rune of Primal Tenacity", quality = 4, entry = 2317, desc = "Reduces the duration of fear effects by 30%, reduces all damage taken while stunned by 30% while in Cat Form." },
    [4803] = { name = "Rune of Living Spirit", quality = 4, entry = 2318, desc = "Increases your total Spirit by 15%." },
    [4804] = { name = "Rune of Pyromaniac", quality = 4, entry = 2319, desc = "Increases chance to critically hit by 3% and allows 25% of your mana regeneration to continue while casting." },
    [4807] = { name = "Rune of Improved Leader of the Pack", quality = 4, entry = 2320, desc = "Your Leader of the Pack ability also causes affected targets to heal themselves for 4% of their total health when they critically hit with a melee or ranged attack.  The healing effect cannot occur more than once every 6 sec.  In addition, you gain 16% of your maximum mana when you benefit from this heal." },
    [4808] = { name = "Rune of Animal Handler", quality = 4, entry = 2321, desc = "Increases your pet's attack power by 12%, and increases the duration of your Master's Call effect by 6 sec." },
    [4809] = { name = "Rune of Ferocious Inspiration", quality = 4, entry = 2322, desc = "All party and raid members have all damage increased by 3% within 100 yards of your pet. In addition, increases the damage dealt by Arcane Shot and Steady Shot by 9%." },
    [4810] = { name = "Rune of Catlike Reflexes", quality = 4, entry = 2323, desc = "Increases your chance to dodge by 3% and your pet's chance to dodge by an additional 12%. In addition, reduces the cooldown of your Kill Command ability by 30 sec." },
    [4811] = { name = "Rune of Serpent's Swiftness", quality = 4, entry = 2324, desc = "Increases ranged combat attack speed by 20% and your pet's melee attack speed by 20%." },
    [4812] = { name = "Rune of Combat Experience", quality = 4, entry = 2325, desc = "Increases your total Agility and Intellect by 4%." },
    [4813] = { name = "Rune of Careful Aim", quality = 4, entry = 2326, desc = "Increases your ranged attack power by an amount equal to 60% of your total Intellect." },
    [4814] = { name = "Rune of Master Marksman", quality = 4, entry = 2327, desc = "Increases your critical strike chance by 6%, and reduces the Mana cost of your Steady Shot, Aimed Shot, and Chimera Shot by 20%." },
    [4815] = { name = "Rune of Resourcefulness", quality = 4, entry = 2328, desc = "Reduces the mana cost of all traps, melee abilities and Black Arrow by 60% and reduces the cooldown of all traps and Black Arrow by 10 sec." },
    [4816] = { name = "Rune of Survival Instincts", quality = 4, entry = 2329, desc = "Reduces all damage taken by 4% and increases the critical strike chance of your Arcane Shot, Steady Shot, and Explosive Shot by 6%." },
    [4817] = { name = "Rune of Thrill of the Hunt", quality = 4, entry = 2330, desc = "Gives you a 100% chance to regain 40% of the mana cost of any shot when it critically hits." },
    [4818] = { name = "Rune of Expose Weakness", quality = 4, entry = 2331, desc = "Your ranged criticals have a 100% chance to grant you Expose Weakness. Expose Weakness increases your attack power by 30% of your Agility for 7 sec." },
    [4819] = { name = "Rune of The Beast Within", quality = 4, entry = 2332, desc = "Increases all damage you deal by 10% and while your pet is under the effects of Bestial Wrath, you also go into a rage causing 15% additional damage and reducing mana costs of all spells by 50% for 6 sec.  While enraged, you do not feel pity or remorse or fear and you cannot be stopped unless killed." },
    [4820] = { name = "Rune of Master Tactician", quality = 4, entry = 2333, desc = "Your successful ranged attacks have a 15% chance to increase your critical strike chance with all attacks by 9% for 8 sec." },
    [4821] = { name = "Rune of Holy Concentration", quality = 4, entry = 2334, desc = "Your mana regeneration from spirit is increased by 50% for 8 sec after you critically heal with Flash Heal, Greater Heal, Binding Heal or Empowered Renew." },
    [4822] = { name = "Rune of Enlightenment", quality = 4, entry = 2335, desc = "Increases your total Spirit by 3% and increases your spell haste by 3%." },
    [4823] = { name = "Rune of Backlash", quality = 4, entry = 2336, desc = "Increases your critical strike chance with spells by an additional 3% and gives you a 25% chance when hit by a physical attack to reduce the cast time of your next Shadow Bolt or Incinerate spell by 100%.  This effect lasts 12 sec and will not occur more than once every 8 seconds." },
    [4824] = { name = "Rune of Rapid Killing", quality = 4, entry = 2337, desc = "Reduces the cooldown of your Rapid Fire ability by 1 min.  In addition, after killing an opponent that yields experience or honor, your next Aimed Shot, Arcane Shot or Chimera Shot causes 20% additional damage.  Lasts 20 sec." },
    [4825] = { name = "Rune of Go for the Throat", quality = 4, entry = 2338, desc = "Your ranged critical hits cause your pet to generate 30 Focus." },
    [4826] = { name = "Rune of Focused Fire", quality = 4, entry = 2339, desc = "All damage caused by you is increased by 2% while your pet is active and the critical strike chance of your pet's special abilities is increased by 20% while Kill Command is active." },
    [4827] = { name = "Rune of Concussive Barrage", quality = 4, entry = 2340, desc = "Your successful Chimera Shot and Multi-Shot attacks have a 100% chance to Daze the target for 4 sec." },
    [4828] = { name = "Rune of Improved Barrage", quality = 4, entry = 2341, desc = "Increases the critical strike chance of your Multi-Shot and Aimed Shot abilities by 15% and reduces the pushback suffered from damaging attacks while channeling Volley by 100%." },
    [4829] = { name = "Rune of Nature's Majesty", quality = 4, entry = 2342, desc = "Increases the critical strike chance of your Wrath, Starfire, Starfall, Nourish and Healing Touch spells by 6%." },
    [4830] = { name = "Rune of Sanctity of Battle", quality = 4, entry = 2343, desc = "Increases your chance to critically hit with all spells and attacks by 3% and increases the damage caused by Exorcism and Crusader Strike by 15%." },
    [4831] = { name = "Rune of Improved Mortal Strike", quality = 4, entry = 2344, desc = "Increases the damage caused by your Mortal Strike ability by 10% and reduces the cooldown by 2 sec." },
    [4832] = { name = "Rune of Combat Potency", quality = 4, entry = 2345, desc = "Gives your successful off-hand melee attacks a 20% chance to generate 15 Energy." },
    [4833] = { name = "Rune of Spell Power", quality = 4, entry = 2346, desc = "Increases critical strike damage bonus of all spells by 50%." },
    [4834] = { name = "Rune of Demonic Knowledge", quality = 4, entry = 2347, desc = "Increases your spell damage by an amount equal to 12% of the total of your active demon's Stamina plus Intellect." },
    [4835] = { name = "Rune of Primal Fury", quality = 4, entry = 2348, desc = "Gives you a 100% chance to gain an additional 5 Rage anytime you get a critical strike while in Bear and Dire Bear Form and your critical strikes from Cat Form abilities that add combo points  have a 100% chance to add an additional combo point." },
    [4836] = { name = "Rune of Shamanistic Focus", quality = 4, entry = 2349, desc = "Reduces the mana cost of your Shock spells by 60%." },
    [4837] = { name = "Rune of Arcane Flows", quality = 4, entry = 2350, desc = "Reduces the cooldown of your Presence of Mind, Arcane Power and Invisibility spells by 30% and the cooldown of your Evocation spell by 2 min." },
    [4838] = { name = "Rune of Incanter's Absorption", quality = 4, entry = 2351, desc = "When your Mana Shield, Frost Ward, Fire Ward, or Ice Barrier absorbs damage your spell damage is increased by 15% of the amount absorbed for 10 sec." },
    [4839] = { name = "Rune of Student of the Mind", quality = 4, entry = 2352, desc = "Increases your total Spirit by 15%." },
    [4840] = { name = "Rune of Netherwind Presence", quality = 4, entry = 2353, desc = "Increases your spell haste by 6%." },
    [4841] = { name = "Rune of Firestarter", quality = 4, entry = 2354, desc = "Your damaging Blast Wave and Dragon's Breath spells have a 100% chance to make your next Flamestrike spell instant cast and cost no mana.  Lasts 10 sec." },
    [4842] = { name = "Rune of Hot Streak", quality = 4, entry = 2355, desc = "Any time you score 2 non-periodic spell criticals in a row using Fireball, Fire Blast, Scorch, Living Bomb, or Frostfire Bolt, you have a 100% chance the next Pyroblast spell cast within 10 sec will be instant cast." },
    [4843] = { name = "Rune of Burnout", quality = 4, entry = 2356, desc = "Increases your spell critical damage bonus with all spells by 50% but your non-periodic spell criticals cost an additional 5% of the spell's cost." },
    [4844] = { name = "Rune of Fingers of Frost", quality = 4, entry = 2357, desc = "Gives your Chill effects a 15% chance to grant you the Fingers of Frost effect, which treats your next 2 spells cast as if the target were Frozen.  Lasts 15 sec." },
    [4845] = { name = "Rune of Brain Freeze", quality = 4, entry = 2358, desc = "Your Frost damage spells with chilling effects have a 15% chance to cause your next Fireball or Frostfire Bolt spell to be instant cast and cost no mana." },
    [4846] = { name = "Rune of Enduring Winter", quality = 4, entry = 2359, desc = "Increases the duration of your Summon Water Elemental spell by 15 sec and your Frostbolt spell has a 100% chance to grant up to 10 party or raid members mana regeneration equal to 1% of their maximum mana per 5 sec for 15 sec.  This effect cannot occur more often than once every 6 sec." },
    [4847] = { name = "Rune of Chilled to the Bone", quality = 4, entry = 2360, desc = "Increases the damage caused by your Frostbolt, Frostfire Bolt and Ice Lance spells by 3% and reduces the movement speed of all chilled targets by an additional 6%." },
    [4848] = { name = "Rune of Focused Will", quality = 4, entry = 2361, desc = "Increases your spell critical effect chance by 3%, and after taking a critical hit you gain the Focused Will effect, reducing all damage taken by 4% and increasing healing effects on you by 3%.  Stacks up to 3 times.  Lasts 8 sec." },
    [4849] = { name = "Rune of Trauma", quality = 4, entry = 2362, desc = "Your melee critical strikes increase the effectiveness of Bleed effects on the target by 30% for 1 min." },
    [4850] = { name = "Rune of Unrelenting Assault", quality = 4, entry = 2363, desc = "Reduces the cooldown of your Overpower and Revenge abilities by 1 secs and increases the damage done by both abilities by 20%.  In addition, if you strike a player with Overpower while they are casting, their magical damage and healing will be reduced by 50% for 6 sec." },
    [4851] = { name = "Rune of Strength of Arms", quality = 4, entry = 2364, desc = "Increases your total Strength and Stamina by 4% and your Expertise by 4." },
    [4852] = { name = "Rune of Furious Attacks", quality = 4, entry = 2365, desc = "Your normal melee attacks have a chance to reduce all healing done to the target by 25% for 10 sec.  This can stack up to 2 times.  This occurs more often than Furious Attacks (Rank 1)." },
    [4853] = { name = "Rune of Bloodsurge", quality = 4, entry = 2366, desc = "Your Heroic Strike, Bloodthirst, and Whirlwind hits have a 20% chance of making your next Slam instant for 5 sec." },
    [4854] = { name = "Rune of Safeguard", quality = 4, entry = 2367, desc = "Reduces damage taken by the target of your Intervene ability by 10% for 5 sec." },
    [4855] = { name = "Rune of Sword and Board", quality = 4, entry = 2368, desc = "Increases the critical strike chance of your Devastate ability by 15% and when your Devastate or Revenge ability deals damage it has a 30% chance of refreshing the cooldown of your Shield Slam ability and reducing its cost by 100% for 5 sec." },
    [4856] = { name = "Rune of Eradication", quality = 4, entry = 2369, desc = "When you deal damage with Corruption, you have 15% chance to increase your spell casting speed by 20% for 10 sec." },
    [4857] = { name = "Rune of Death's Embrace", quality = 4, entry = 2370, desc = "Increases the amount drained by your Drain Life by 30% while your health is at or below 20% health, and increases the damage done by your Shadow spells by 12% when your target is at or below 35% health." },
    [4858] = { name = "Rune of Everlasting Affliction", quality = 4, entry = 2371, desc = "Your Corruption and Unstable Affliction spells gain an additional 5% of your bonus spell damage, and your Drain Life, Drain Soul, Shadow Bolt, and Haunt spells have a 100% chance to reset the duration of your Corruption spell on the target." },
    [4859] = { name = "Rune of Empowered Imp", quality = 4, entry = 2372, desc = "Increases the damage done by your Imp by 30%, and all critical hits done by your Imp have a 100% chance to increase your spell critical hit chance for your next spell by 100%. This effect lasts 8 sec." },
    [4860] = { name = "Rune of Fel Synergy", quality = 4, entry = 2373, desc = "You have a 100% chance to heal your pet for 15% of the amount of spell damage done by you." },
    [4861] = { name = "Rune of Demonic Pact", quality = 4, entry = 2374, desc = "Increases your spell damage by 3%, and your pet's criticals apply the Demonic Pact effect to your party or raid members. Demonic Pact increases spell power by 6% of your Spell Damage for 45 sec. This effect has a 20 sec cooldown. Does not work on Enslaved demons." },
    [4862] = { name = "Rune of Molten Core", quality = 4, entry = 2375, desc = "Increases the duration of your Immolate by 9 sec, and you have a 12% chance to gain the Molten Core effect when your Corruption deals damage. The Molten Core effect empowers your next 3 Incinerate or Soul Fire spells cast within 15 sec." },
    [4863] = { name = "Rune of Backdraft", quality = 4, entry = 2376, desc = "When you cast Conflagrate, the cast time and global cooldown of your next three Destruction spells is reduced by 25%. Lasts 15 sec." },
    [4864] = { name = "Rune of Fire and Brimstone", quality = 4, entry = 2377, desc = "Increases the damage done by your Incinerate and Chaos Bolt spells to targets afflicted by your Immolate by 10%, and the critical strike chance of your Conflagrate spell is increased by 25%." },
    [4865] = { name = "Rune of Critical Block", quality = 4, entry = 2378, desc = "Your successful blocks have a 60% chance to block double the normal amount and increases your chance to critically hit with your Shield Slam ability by an additional 10%." },
    [4866] = { name = "Rune of Aspiration", quality = 4, entry = 2379, desc = "Reduces the cooldown of your Inner Focus, Power Infusion, Pain Suppression and Penance spells by 20%." },
    [4867] = { name = "Rune of Divine Aegis", quality = 4, entry = 2380, desc = "Critical heals create a protective shield on the target, absorbing 10% of the amount healed. Lasts 12 sec." },
    [4868] = { name = "Rune of Grace", quality = 4, entry = 2381, desc = "Your Flash Heal, Greater Heal, and Penance spells have a 100% chance to bless the target with Grace, increasing all healing received from the Priest by 3%. This effect will stack up to 3 times. Effect lasts 12 sec. Grace can only be active on one target at a time." },
    [4869] = { name = "Rune of Rapture", quality = 4, entry = 2382, desc = "When your Power Word: Shield is completely absorbed or dispelled you are instantly energized with 2.5% of your total mana, and you have a 100% chance to energize your shielded target with 2% total mana, 8 rage, 16 energy or 32 runic power. This effect can only occur once every 12 sec." },
    [4871] = { name = "Rune of Test of Faith", quality = 4, entry = 2383, desc = "Increases healing by 12% on friendly targets at or below 50% health." },
    [4872] = { name = "Rune of Divine Providence", quality = 4, entry = 2384, desc = "Increases the amount healed by Circle of Healing, Binding Heal, Holy Nova, Prayer of Healing, Divine Hymn and Prayer of Mending by 9%, and reduces the cooldown of your Prayer of Mending by 18%." },
    [4873] = { name = "Rune of Improved Shadowform", quality = 4, entry = 2385, desc = "Your Fade ability now has a 100% chance to remove all movement impairing effects when used while in Shadowform, and reduces casting or channeling time lost when damaged by 100% when casting any Shadow spell while in Shadowform." },
    [4874] = { name = "Rune of Pain and Suffering", quality = 4, entry = 2386, desc = "Your Mind Flay has a 100% chance to refresh the duration of your Shadow Word: Pain on the target, and reduces the damage you take from your own Shadow Word: Death by 30%." },
    [4875] = { name = "Rune of Owlkin Frenzy", quality = 4, entry = 2387, desc = "Attacks done to you while in Moonkin form have a 15% chance to cause you to go into a Frenzy, increasing your damage by 10%, cause you to be immune to pushback while casting Balance spells and restore 2% base mana every 2 sec. Lasts 10 sec." },
    [4876] = { name = "Rune of Improved Moonkin Form", quality = 4, entry = 2388, desc = "Your Moonkin Aura also causes affected targets to gain 3% haste and you to gain 30% of your spirit as additional spell damage." },
    [4878] = { name = "Rune of Primal Precision", quality = 4, entry = 2389, desc = "Increases your expertise by 10, and you are refunded 80% of the energy cost of a finishing move if it fails to land." },
    [4879] = { name = "Rune of Master Shapeshifter", quality = 4, entry = 2390, desc = "Grants an effect which lasts while the Druid is within the respective shapeshift form." },
    [4880] = { name = "Rune of Infected Wounds", quality = 4, entry = 2391, desc = "Your Shred, Maul, and Mangle attacks cause an Infected Wound in the target. The Infected Wound reduces the movement speed of the target by 50% and the attack speed by 20%. Lasts 12 sec." },
    [4881] = { name = "Rune of Improved Mangle", quality = 4, entry = 2392, desc = "Reduces the cooldown of your Mangle (Bear) ability by 1.5.1 sec., and reduces the energy cost of your Mangle (Cat) ability by 6." },
    [4882] = { name = "Rune of King of the Jungle", quality = 4, entry = 2393, desc = "While using your Enrage ability in Bear Form or Dire Bear Form, your damage is increased by 15%, and your Tiger's Fury ability also instantly restores 60 energy.  In addition, the mana cost of Bear Form, Cat Form, and Dire Bear Form is reduced by 60%." },
    [4883] = { name = "Rune of Living Seed", quality = 4, entry = 2394, desc = "When you critically heal your target with Swiftmend, Regrowth, Nourish or Healing Touch spell you have a 100% chance to plant a Living Seed on the target for 30% of the amount healed. The Living Seed will bloom when the target is next attacked. Lasts 15 sec." },
    [4884] = { name = "Rune of Earth and Moon", quality = 4, entry = 2395, desc = "Your Wrath and Starfire spells have a 100% chance to apply the Earth and Moon effect, which increases spell damage taken by 10% for 8 sec.  Also increases your spell damage by 6%." },
    [4885] = { name = "Rune of Gale Winds", quality = 4, entry = 2396, desc = "Increases damage done by your Hurricane and Typhoon spells by 30%, and increases the range of your Cyclone spell by 6 yards." },
    [4886] = { name = "Rune of Eclipse", quality = 4, entry = 2397, desc = "When you critically hit with Starfire, you have a 100% chance of increasing damage done by Wrath by 30%. When you critically hit with Wrath, you have a 60% chance of increasing your critical strike chance with Starfire by 30%. Each effect lasts 15 sec and each has a separate 30 sec cooldown.  Both effects cannot occur simultaneously." },
    [4887] = { name = "Rune of Improved Tree of Life", quality = 4, entry = 2398, desc = "Increases your armor contribution from items while in Tree of Life Form by 15%, and increases your healing spell power by 15% of your spirit while in Tree of Life Form." },
    [4888] = { name = "Rune of Revitalize", quality = 4, entry = 2399, desc = "Your Rejuvenation and Wild Growth spells have a 15% chance to restore 8 Energy, 4 Rage, 1% Mana or 16 Runic Power per tick." },
    [4889] = { name = "Rune of Unholy Blight", quality = 4, entry = 2400, desc = "Causes the victims of your Death Coil to be surrounded by a vile swarm of unholy insects, taking 10% of the damage done by the Death Coil over 10 sec, and preventing any diseases on the victim from being dispelled." },
    [4890] = { name = "Rune of Bladed Armor", quality = 4, entry = 2401, desc = "Increases your attack power by 5 for every 180 armor value you have." },
    [4891] = { name = "Rune of Bloody Strikes", quality = 4, entry = 2402, desc = "Increases the damage of Blood Strike by 15% and Heart Strike by 45%, and increases the damage of Blood Boil by 30%." },
    [4892] = { name = "Rune of Dark Conviction", quality = 4, entry = 2403, desc = "Increases your chance to critically hit with weapons, spells and abilities by 5%." },
    [4893] = { name = "Rune of Butchery", quality = 4, entry = 2404, desc = "Whenever you kill an enemy that grants experience or honor, you generate up to 20 runic power.  In addition, you generate 2 runic power per 5 sec while in combat." },
    [4894] = { name = "Rune of Improved Rune Tap", quality = 4, entry = 2405, desc = "Increases the health provided by Rune Tap by 100% and lowers its cooldown by 30 sec." },
    [4895] = { name = "Rune of Subversion", quality = 4, entry = 2406, desc = "Increases the critical strike chance of Blood Strike, Scourge Strike, Heart Strike and Obliterate by 9%, and reduces threat generated while in Blood or Unholy Presence by 25%." },
    [4896] = { name = "Rune of Spell Deflection", quality = 4, entry = 2407, desc = "You have a chance equal to your Parry chance of taking 45% less damage from a direct damage spell." },
    [4897] = { name = "Rune of Bloody Vengeance", quality = 4, entry = 2408, desc = "Gives you a 3% bonus to physical damage you deal for 30 sec after dealing a critical strike from a weapon swing, spell, or ability.  This effect stacks up to 3 times." },
    [4898] = { name = "Rune of Scent of Blood", quality = 4, entry = 2409, desc = "You have a 15% chance after dodging, parrying or taking  direct damage to gain the Scent of Blood effect, causing your next 3 melee hits to generate 10 runic power." },
    [4899] = { name = "Rune of Sudden Doom", quality = 4, entry = 2410, desc = "Your Blood Strikes and Heart Strikes have a 15% chance to launch a free Death Coil at your target." },
    [4901] = { name = "Rune of Might of Mograine", quality = 4, entry = 2411, desc = "Increases the critical strike damage bonus of your Blood Boil, Blood Strike, Death Strike, and Heart Strike abilities by 45%." },
    [4902] = { name = "Rune of Merciless Combat", quality = 4, entry = 2412, desc = "Your Icy Touch, Howling Blast, Obliterate and Frost Strike do an additional 12% damage when striking targets with less than 35% health." },
    [4903] = { name = "Rune of Bloodworms", quality = 4, entry = 2413, desc = "Your weapon hits have a 9% chance to cause the target to spawn 2-4 Bloodworms.  Bloodworms attack your enemies, healing you as they do damage for 20 sec or until killed." },
    [4904] = { name = "Rune of Epidemic", quality = 4, entry = 2414, desc = "Increases the duration of Blood Plague and Frost Fever by 6 sec." },
    [4905] = { name = "Rune of Morbidity", quality = 4, entry = 2415, desc = "Increases the damage and healing of Death Coil by 15% and reduces the cooldown on Death and Decay by 15 sec." },
    [4906] = { name = "Rune of Virulence", quality = 4, entry = 2416, desc = "Increases your chance to hit with your spells by 3% and reduces the chance that your damage over time diseases can be cured by 30%." },
    [4907] = { name = "Rune of Ravenous Dead", quality = 4, entry = 2417, desc = "Increases your total Strength by 3% and the contribution your Ghouls get from your Strength and Stamina by 60%" },
    [4908] = { name = "Rune of Unholy Command", quality = 4, entry = 2418, desc = "Reduces the cooldown of your Death Grip ability by 10 sec." },
    [4909] = { name = "Rune of Dirge", quality = 4, entry = 2419, desc = "Your Death Strike, Plague Strike and Scourge Strike generate 5 additional runic power." },
    [4910] = { name = "Rune of Magic Suppression", quality = 4, entry = 2420, desc = "You take 6% less damage from all magic.  In addition, your Anti-Magic Shell absorbs an additional 25% of spell damage." },
    [4911] = { name = "Rune of Blood-Caked Blade", quality = 4, entry = 2421, desc = "Your auto attacks have a 30% chance to cause a Blood-Caked Strike, which hits for 25% weapon damage plus 12.5.1% for each of your diseases on the target." },
    [4912] = { name = "Rune of Crypt Fever", quality = 4, entry = 2422, desc = "Your diseases also cause Crypt Fever, which increases disease damage taken by the target by 30%." },
    [4913] = { name = "Rune of Wandering Plague", quality = 4, entry = 2423, desc = "When your diseases damage an enemy, there is a chance equal to your melee critical strike chance that they will cause 100% additional damage to the target and all enemies within 8 yards.  Ignores any target under the effect of a spell that is cancelled by taking damage." },
    [4914] = { name = "Rune of Endless Winter", quality = 4, entry = 2424, desc = "Your strength is increased by 4% and your Mind Freeze no longer costs runic power." },
    [4915] = { name = "Rune of Black Ice", quality = 4, entry = 2425, desc = "Increases your Frost and Shadow damage by 10%." },
    [4916] = { name = "Rune of Toughness", quality = 4, entry = 2426, desc = "Increases your armor value from items by 10% and reduces the duration of all movement slowing effects by 30%." },
    [4917] = { name = "Rune of Glacier Rot", quality = 4, entry = 2427, desc = "Diseased enemies take 20% more damage from your Icy Touch, Howling Blast and Frost Strike." },
    [4918] = { name = "Rune of Veteran of the Third War", quality = 4, entry = 2428, desc = "Increases your total Strength by 6%, your Stamina by 3%, and your expertise by 6." },
    [4919] = { name = "Rune of Death Rune Mastery", quality = 4, entry = 2429, desc = "Whenever you hit with Death Strike or Obliterate there is a 100% chance that the Frost and Unholy Runes will become Death Runes when they activate.  Death Runes count as a Blood, Frost or Unholy Rune." },
    [4920] = { name = "Rune of Chilblains", quality = 4, entry = 2430, desc = "Victims of your Frost Fever disease are Chilled, reducing movement speed by 50% for 10 sec." },
    [4921] = { name = "Rune of Chill of the Grave", quality = 4, entry = 2431, desc = "Your Chains of Ice, Howling Blast, Icy Touch and Obliterate generate 5 additional runic power." },
    [4922] = { name = "Rune of Rage of Rivendare", quality = 4, entry = 2432, desc = "Your spells and abilities deal 10% more damage to targets infected with Blood Plague.  Also increases your expertise by 5." },
    [4923] = { name = "Rune of Tundra Stalker", quality = 4, entry = 2433, desc = "Your spells and abilities deal 15% more damage to targets infected with Frost Fever.  Also increases your expertise by 5." },
    [4924] = { name = "Rune of Nerves of Cold Steel", quality = 4, entry = 2434, desc = "Increases your chance to hit with one-handed melee weapons by 3% and increases the damage done by your offhand weapon by 25%." },
    [4925] = { name = "Rune of Runic Power Mastery", quality = 4, entry = 2435, desc = "Increases your maximum Runic Power by 20." },
    [4926] = { name = "Rune of Will of the Necropolis", quality = 4, entry = 2436, desc = "Damage that would take you below 35% health or taken while you are at 35% health is reduced by 15%." },
    [4927] = { name = "Rune of Acclimation", quality = 4, entry = 2437, desc = "When you are hit by a spell, you have a 30% chance to boost your resistance to that type of magic for 18 sec.  Stacks up to 3 times." },
    [4939] = { name = "Rune of Guile of Gorefiend", quality = 4, entry = 2438, desc = "Increases the critical strike damage bonus of your Blood Strike, Frost Strike, Howling Blast and Obliterate abilities by 45%, and increases the duration of your Icebound Fortitude by 6 secs." },
    [4943] = { name = "Rune of Improved Blood Presence", quality = 4, entry = 2439, desc = "While in Frost Presence or Unholy Presence, you retain 4% healing from Blood Presence, and healing done to you is increased by 10% in Blood Presence." },
    [4944] = { name = "Rune of Improved Frost Presence", quality = 4, entry = 2440, desc = "While in Blood Presence or Unholy Presence, you retain 8% stamina from Frost Presence, and damage done to you is decreased by an additional 2% in Frost Presence." },
    [4949] = { name = "Rune of Improved Unholy Presence", quality = 4, entry = 2441, desc = "While in Blood Presence or Frost Presence, you retain 15% increased movement speed from Unholy Presence, and your runes finish their cooldowns 10% faster in Unholy Presence." },
    [4953] = { name = "Rune of Incite", quality = 4, entry = 2442, desc = "Increases the critical strike chance of your Heroic Strike, Thunder Clap and Cleave abilities by 12%." },
    [4956] = { name = "Rune of Icy Talons", quality = 4, entry = 2443, desc = "You leech heat from victims of your Frost Fever, so that when their melee attack speed is reduced, yours increases by 20% for the next 20 sec." },
    [4957] = { name = "Rune of Frigid Dreadplate", quality = 4, entry = 2444, desc = "Reduces the chance melee attacks will hit you by 3%." },
    [4958] = { name = "Rune of Killing Machine", quality = 4, entry = 2445, desc = "Your melee attacks have a chance to make your next Icy Touch, Howling Blast or Frost Strike a critical strike.  Effect occurs more often than Killing Machine (Rank 4)." },
    [4959] = { name = "Rune of Ebon Plaguebringer", quality = 4, entry = 2446, desc = "Your Crypt Fever morphs into Ebon Plague, which increases magic damage taken by 13% in addition to increasing disease damage taken.  Improves your critical strike chance with weapons and spells by 3% at all times." },
    [4963] = { name = "Rune of Twisted Faith", quality = 4, entry = 2447, desc = "Increases your spell power by 12% of your total Spirit, and your damage done by your Mind Flay and Mind Blast is increased by 9% if your target is afflicted by your Shadow Word: Pain." },
    [4964] = { name = "Rune of Gift of the Earthmother", quality = 4, entry = 2448, desc = "Increases your total spell haste by 10% and reduces the base cooldown of your Lifebloom spell by 10%." },
    [4965] = { name = "Rune of On a Pale Horse", quality = 4, entry = 2449, desc = "You become as hard to stop as death itself.  The duration of all Stun and Fear effects used against you is reduced by 20%, and your mounted speed is increased by 20%.  This does not stack with other movement speed increasing effects." },
    [4966] = { name = "Rune of Rend and Tear", quality = 4, entry = 2450, desc = "Increases damage done by your Maul and Shred attacks on bleeding targets by 20%, and increases the critical strike chance of your Ferocious Bite ability on bleeding targets by 25%." },
    [4967] = { name = "Rune of Improved Icy Touch", quality = 4, entry = 2451, desc = "Your Icy Touch does an additional 15% damage and your Frost Fever reduces melee and ranged attack speed by an additional 6%." },
    [4968] = { name = "Rune of Necrosis", quality = 4, entry = 2452, desc = "Your auto attacks deal an additional 20% Shadow damage." },
    [4969] = { name = "Rune of Elemental Oath", quality = 4, entry = 2453, desc = "While Clearcasting from Elemental Focus is active, you deal 10% more spell damage. In addition, party and raid members within 100 yards receive a 3% bonus to their spell critical strike chance." },
    [4973] = { name = "Rune of Annihilation", quality = 4, entry = 2454, desc = "Increases the critical strike chance of your melee special abilities by 3%.  In addition, there is a 100% chance that your Obliterate will do its damage without consuming diseases." },
    [4988] = { name = "Rune of Astral Shift", quality = 4, entry = 2455, desc = "When stunned, feared or silenced you shift into the Astral Plane reducing all damage taken by 10% for the duration of the stun, fear or silence effect." },
    [4989] = { name = "Rune of Lava Flows", quality = 4, entry = 2456, desc = "Increases the critical strike damage bonus of your Lava Burst spell by an additional 24%, and when your Flame Shock is dispelled your spell casting speed is increased by 30% for 6 sec." },
    [4990] = { name = "Rune of Storm- Earth and Fire", quality = 4, entry = 2457, desc = "Reduces the cooldown of your Chain Lightning spell by 2.5 sec, your Earthbind Totem also has a 100% chance to root targets for 5 sec when cast and the periodic damage done by your Flame Shock is increased by 60%." },
    [4991] = { name = "Rune of Improved Stormstrike", quality = 4, entry = 2458, desc = "When you Stormstrike, you have a 100% chance to immediately grant you 20% of your base mana." },
    [4992] = { name = "Rune of Earthen Power", quality = 4, entry = 2459, desc = "Your Earthbind Totem's pulses have a 100% chance to also remove all snare effects from you and nearby friendly targets, and your Earth Shock reduces enemy attack speed by an additional 10%." },
    [4993] = { name = "Rune of Static Shock", quality = 4, entry = 2460, desc = "You have a 15% chance to hit your target with a Lightning Shield orb charge when you deal damage with melee attacks and abilities, and your Lightning Shield gains 6 additional charges." },
    [4994] = { name = "Rune of Maelstrom Weapon", quality = 4, entry = 2461, desc = "When you deal damage with a melee weapon, you have a chance (higher than rank 4) to reduce the cast time of your next Lightning Bolt, Chain Lightning, Lesser Healing Wave, Healing Wave, Chain Heal, or Hex spell by 20%. Stacks up to 5 times. Lasts 30 sec." },
    [4995] = { name = "Rune of Blessing of the Eternals", quality = 4, entry = 2462, desc = "Increases the critical effect chance of your spells by 4%, and increases the chance to apply the Earthliving heal over time effect on the target by 80% when they are at or under 35% total health." },
    [5008] = { name = "Rune of Ancestral Awakening", quality = 4, entry = 2463, desc = "When you critically heal with your Healing Wave, Lesser Healing Wave or Riptide you summon an Ancestral spirit to aid you, instantly healing the lowest percentage health friendly party or raid target within 40 yards for 30% of the amount healed." },
    [5013] = { name = "Rune of Improved Earth Shield", quality = 4, entry = 2464, desc = "Increases the amount of charges for your Earth Shield by 3, and increases the healing done by your Earth Shield by 15%." },
    [5014] = { name = "Rune of Tidal Waves", quality = 4, entry = 2465, desc = "When you cast Chain Heal or Riptide, you have a 60% chance to lower the cast time of your Healing Wave spell by 30% and increase the critical effect chance of your Lesser Healing Wave spell by 25%, until two such spells have been cast. In addition, your Healing Wave gains an additional 12% of your bonus healing effects and your Lesser Healing Wave gains an additional 6% of your bonus healing effects." },
    [5015] = { name = "Rune of Deadly Brew", quality = 4, entry = 2466, desc = "When you apply Instant, Wound or Mind-Numbing poison to a target, you have a 100% chance to apply Crippling poison." },
    [5018] = { name = "Rune of Turn the Tables", quality = 4, entry = 2467, desc = "Whenever anyone in your party or raid blocks, dodges, or parries an attack your chance to critically hit with all combo moves is increased by 6% for 8 sec." },
    [5022] = { name = "Rune of Blood Spatter", quality = 4, entry = 2468, desc = "Increases the damage caused by your Garrote and Rupture abilities by 30%." },
    [5023] = { name = "Rune of Focused Attacks", quality = 4, entry = 2469, desc = "Your melee critical strikes have a 100% chance to give you 3 energy." },
    [5027] = { name = "Rune of Cut to the Chase", quality = 4, entry = 2470, desc = "Your Eviscerate and Envenom abilities have a 100% chance to refresh your Slice and Dice duration to its 5 combo point maximum." },
    [5028] = { name = "Rune of Unfair Advantage", quality = 4, entry = 2471, desc = "Whenever you dodge an attack you gain an Unfair Advantage, striking back for 100% of your main hand weapon's damage.  This cannot occur more than once per second." },
    [5029] = { name = "Rune of Throwing Specialization", quality = 4, entry = 2472, desc = "Increases the range of Throw and Deadly Throw by 4 yards and gives your Deadly Throw a 100% chance to interrupt the target for 3 sec." },
    [5030] = { name = "Rune of Prey on the Weak", quality = 4, entry = 2473, desc = "Your critical strike damage is increased by 10% when the target has less health than you (as a percentage of total health)." },
    [5031] = { name = "Rune of Waylay", quality = 4, entry = 2474, desc = "Your Ambush and Backstab hits have a 100% chance to unbalance a target, increasing the time between their melee and ranged attacks by 20%, and reducing movement speed by 50% for 8 sec." },
    [5032] = { name = "Rune of Honor Among Thieves", quality = 4, entry = 2475, desc = "When anyone in your group critically hits with a damage or healing spell or ability, you have a 100% chance to gain a combo point on your current target.  This effect cannot occur more than once every second." },
    [5033] = { name = "Rune of Slaughter from the Shadows", quality = 4, entry = 2476, desc = "Reduces the energy cost of your Backstab and Ambush abilities by 10 and the energy cost of your Hemorrhage by 3, and increases all damage done by 3%." },
    [5034] = { name = "Rune of Vicious Strikes", quality = 4, entry = 2477, desc = "Increases the critical strike chance by 6% and critical strike damage bonus by 30% of your Plague Strike and Scourge Strike." },
    [5035] = { name = "Rune of Improved Shields", quality = 4, entry = 2478, desc = "Increases the damage done by your Lightning Shield orbs by 60%, increases the amount of mana gained from your Water Shield orbs by 15% and increases the amount of healing done by your Earth Shield orbs by 15%." },
    [5036] = { name = "Rune of Master of Ghouls", quality = 4, entry = 2479, desc = "Reduces the cooldown on Raise Dead by 60 sec, and the Ghoul summoned by your Raise Dead spell is considered a pet under your control.  Unlike normal Death Knight Ghouls, your pet does not have a limited duration." },
    [5037] = { name = "Rune of Enhancing Totems", quality = 4, entry = 2480, desc = "Increases the effect of your Strength of Earth and Flametongue Totems by 15%." },
    [5038] = { name = "Rune of Improved Tracking", quality = 4, entry = 2481, desc = "While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids and Undead, all damage done to those types by the Hunter is increased by 5%." },
    [5039] = { name = "Rune of Borrowed Time", quality = 4, entry = 2482, desc = "Grants 20% spell haste for your next spell after casting Power Word: Shield, and increases the amount absorbed by your Power Word: Shield equal to 40% of your spell power." },
    [5040] = { name = "Rune of Twin Disciplines", quality = 4, entry = 2483, desc = "Increases the damage and healing done by your instant spells by 5%." },
    [5041] = { name = "Rune of Abomination's Might", quality = 4, entry = 2484, desc = "Increases the attack power by 10% of party and raid members within 100 yards.  Also increases your total Strength by 2%." },
    [5042] = { name = "Rune of Wild Quiver", quality = 4, entry = 2485, desc = "You have a 30% chance to shoot an additional shot when doing damage with your auto shot, dealing 60% weapon nature damage. Wild Quiver consumes no ammo." },
    [5043] = { name = "Rune of Improved Steady Shot", quality = 4, entry = 2486, desc = "Your Steady Shot hits have a 15% chance to increase the damage done by your next Aimed Shot, Arcane Shot or Chimera Shot by 15%, and reduce the mana cost of your next Aimed Shot, Arcane Shot or Chimera Shot by 20%." },
    [5044] = { name = "Rune of Rapid Recuperation", quality = 4, entry = 2487, desc = "You gain 4% of your mana every 3 sec while under the effect of Rapid Fire, and you gain 2% of your mana every 2 sec for 6 sec when you gain Rapid Killing." },
    [5045] = { name = "Rune of Piercing Shots", quality = 4, entry = 2488, desc = "Your critical Aimed, Steady and Chimera Shots cause the target to bleed for 25% of the damage dealt over 8 sec." },
    [5046] = { name = "Rune of Marked for Death", quality = 4, entry = 2489, desc = "Increases your damage done by your shots and the damage done by your pet's special abilities by 5% on marked targets, and increases the critical strike damage bonus of your Aimed Shot, Arcane Shot, Steady Shot, Kill Shot and Chimera Shot by 10%." },
    [5047] = { name = "Rune of Invigoration", quality = 4, entry = 2490, desc = "When your pet scores a critical hit with a special ability, you have a 100% chance to instantly regenerate 1% mana." },
    [5050] = { name = "Rune of Cobra Strikes", quality = 4, entry = 2491, desc = "You have a 60% chance when you critically hit with Arcane Shot, Steady Shot or Kill Shot to cause your pet's next 2 special attacks to critically hit." },
    [5051] = { name = "Rune of Longevity", quality = 4, entry = 2492, desc = "Reduces the cooldown of your Bestial Wrath, Intimidation and Pet Special Abilities by 30%." },
    [5052] = { name = "Rune of Aspect Mastery", quality = 4, entry = 2493, desc = "Aspect of the Viper - Reduces the damage penalty by 20%." },
    [5053] = { name = "Rune of Hunting Party", quality = 4, entry = 2494, desc = "Increases your total Agility by an additional 3%, and your Arcane Shot, Explosive Shot and Steady Shot critical strikes have a 100% chance to grant up to 10 party or raid members mana regeneration equal to 1% of the maximum mana per 5 sec. Lasts for 15 sec." },
    [5054] = { name = "Rune of Noxious Stings", quality = 4, entry = 2495, desc = "If Wyvern Sting is dispelled, the dispeller is also afflicted by Wyvern Sting lasting 50% of the duration remaining, and increases all damage done by you on targets afflicted by your Serpent Sting by 3%." },
    [5055] = { name = "Rune of Point of No Escape", quality = 4, entry = 2496, desc = "Increases the critical strike chance of all of your attacks on targets affected by your Frost Trap, Freezing Trap and Freezing Arrow by 6%." },
    [5056] = { name = "Rune of Sniper Training", quality = 4, entry = 2497, desc = "Increases the critical strike chance of your Kill Shot ability by 15%, and while standing still for 6 sec, you gain Sniper Training increasing the damage done by your Steady Shot, Aimed Shot, Black Arrow and Explosive Shot by 3% for 12 sec." },
    [5057] = { name = "Rune of Sanctified Wrath", quality = 4, entry = 2498, desc = "Increases the critical strike chance of Hammer of Wrath by 30%, reduces the cooldown of Avenging Wrath by 60 secs and while affected by Avenging Wrath 50% of all damage caused bypasses damage reduction effects." },
    [5058] = { name = "Rune of Righteous Vengeance", quality = 4, entry = 2499, desc = "When your Judgement, Crusader Strike and Divine Storm spells deal a critical strike, your target will take 20% additional damage over 8 sec." },
    [5059] = { name = "Rune of The Art of War", quality = 4, entry = 2500, desc = "Increases the damage of your Judgement, Crusader Strike and Divine Storm abilities by 9% and when your melee attacks critically hit your next Flash of Light  or Exorcism spell becomes instant cast." },
    [5060] = { name = "Rune of Sheath of Light", quality = 4, entry = 2501, desc = "Your critical healing spells heal the target for 10% of the healed amount over 12 seconds." },
    [5061] = { name = "Rune of Stoicism", quality = 4, entry = 2502, desc = "Reduces the duration of all Stun effects by an additional 30% and reduces the chance your helpful spells and damage over time effects will be dispelled by an additional 30%." },
    [5062] = { name = "Rune of Divine Guardian", quality = 4, entry = 2503, desc = "When Divine Sacrifice is activated, your party and raid members within 30 yards take 20% reduced damage for 6 sec.  In addition, increases the duration of your Sacred Shield by 100% and the amount absorbed by 20%." },
    [5063] = { name = "Rune of Sacred Cleansing", quality = 4, entry = 2504, desc = "Your Cleanse spell has a 30% chance to increase the target's resistance to Disease, Magic and Poison by 30% for 10 sec." },
    [5064] = { name = "Rune of Enlightened Judgements", quality = 4, entry = 2505, desc = "Increases the range of your Judgement of Light and Judgement of Wisdom spells by 20 yards and increases your chance to hit by 4%." },
    [5065] = { name = "Rune of Infusion of Light", quality = 4, entry = 2506, desc = "Your Holy Shock critical hits reduce the cast time of your next Flash of Light by 1.5.1 sec or increase the critical chance of your next Holy Light by 20%.  In addition, causes your Flash of Light to heal targets with Sacred Shield for an additional 100% over 12 sec." },
    [5066] = { name = "Rune of Guarded by the Light", quality = 4, entry = 2507, desc = "Reduces spell damage taken by 6% and gives a 100% chance to refresh the duration of your Divine Plea when you hit an enemy.  In addition, your Divine Plea spell is 100% less likely to be dispelled." },
    [5067] = { name = "Rune of Focused Aim", quality = 4, entry = 2508, desc = "Reduces the pushback suffered from damaging attacks while casting Steady Shot by 70%, and increases your chance to hit by 3%." },
    [5068] = { name = "Rune of Swift Retribution", quality = 4, entry = 2509, desc = "Your auras also increase casting, ranged and melee attack speeds by 3%." },
    [5069] = { name = "Rune of Blessed Hands", quality = 4, entry = 2510, desc = "Reduces the mana cost of Hand of Freedom, Hand of Sacrifice and Hand of Salvation by 30%, increases the effectiveness of Hand of Salvation by 100% and the effectiveness of Hand of Sacrifice by an additional 10%." },
    [5070] = { name = "Rune of Judgements of the Just", quality = 4, entry = 2511, desc = "Reduces the cooldown of your Hammer of Justice by 10 sec, increases the duration of your Seal of Justice effect by 1 sec and your Judgement spells also reduce the melee attack speed of the target by 20%." },
    [5071] = { name = "Rune of Shield of the Templar", quality = 4, entry = 2512, desc = "Reduces all damage taken by 3% and grants your Avenger's Shield a 100% chance to silence your targets for 3 sec." },
    [5072] = { name = "Rune of Improved Fear", quality = 4, entry = 2513, desc = "Causes your Fear spell to inflict a Nightmare on the target when the fear effect ends. The Nightmare effect reduces the target's movement speed by 30% for 5 sec." },
    [5073] = { name = "Rune of Improved Felhunter", quality = 4, entry = 2514, desc = "Your Felhunter regains 8% of its maximum mana each time it hits with its Shadow Bite ability and the cooldown on that ability is reduced by 4 sec.  In addition, increases the effect of your Felhunter's Fel Intelligence by 10%." },
    [5074] = { name = "Rune of Improved Soul Leech", quality = 4, entry = 2515, desc = "Your Soul Leech effect also restores mana to you and your summoned demon equal to 2% of maximum mana, and has a 100% chance to grant up to 10 party or raid members mana regeneration equal to 1% of maximum mana per 5 sec. Lasts for 15 sec." },
    [5075] = { name = "Rune of Judgements of the Pure", quality = 4, entry = 2516, desc = "Increases the damage done by your Seal and Judgement spells by 20%, and your Judgement spells increase your casting and melee haste by 6% for 1 min." },
    [5076] = { name = "Rune of Improved Demonic Tactics", quality = 4, entry = 2517, desc = "Increases your summoned demon's critical strike chance equal to 30% of your critical strike chance." },
    [5077] = { name = "Rune of Prismatic Cloak", quality = 4, entry = 2518, desc = "Reduces all damage taken by 2% and reduces the fade time of your Invisibility spell by 3 sec." },
    [5078] = { name = "Rune of Missile Barrage", quality = 4, entry = 2519, desc = "Gives your Arcane Blast a 40% chance, and your Arcane Barrage, Fireball, Frostbolt and Frostfire Bolt spells a 20% chance to reduce the channeled duration of the next Arcane Missiles spell by 2.5 secs, reduce the mana cost by 100%, and missiles will fire every .5 secs." },
    [5079] = { name = "Rune of Blood of the North", quality = 4, entry = 2520, desc = "Increases Blood Strike and Frost Strike damage by 10%.  In addition, whenever you hit with Blood Strike or Pestilence there is a 100% chance that the Blood Rune will become a Death Rune when it activates.  Death Runes count as a Blood, Frost or Unholy Rune." },
    [5080] = { name = "Rune of Arcane Fortitude", quality = 4, entry = 2521, desc = "Increases your armor by an amount equal to 150% of your Intellect." },
    [5081] = { name = "Rune of Incineration", quality = 4, entry = 2522, desc = "Increases the critical strike chance of your Fire Blast, Scorch, Arcane Blast and Cone of Cold spells by 9%." },
    [5082] = { name = "Rune of Burning Determination", quality = 4, entry = 2523, desc = "When Interrupted or Silenced you have a 100% chance to become immune to the next Interrupt or Silence mechanic.  Lasts 20 sec." },
    [5083] = { name = "Rune of Shattered Barrier", quality = 4, entry = 2524, desc = "Gives your Ice Barrier spell a 100% chance to freeze all enemies within 10 yds for 8 sec when it is destroyed." },
    [5084] = { name = "Rune of Icy Reach", quality = 4, entry = 2525, desc = "Increases the range of your Icy Touch, Chains of Ice and Howling Blast by 10 yards." },
    [5085] = { name = "Rune of Cold as Ice", quality = 4, entry = 2526, desc = "Reduces the cooldown of your Cold Snap, Ice Barrier and Summon Water Elemental spells by 20%." },
    [5086] = { name = "Rune of Ice Floes", quality = 4, entry = 2527, desc = "Reduces the cooldown of your Frost Nova, Cone of Cold, Ice Block and Icy Veins spells by 33%." },
    [5087] = { name = "Rune of Two-Handed Weapon Specialization", quality = 4, entry = 2528, desc = "Increases the damage you deal with two-handed melee weapons by 4%." },
    [5088] = { name = "Rune of Anticipation", quality = 4, entry = 2529, desc = "Increases your Dodge chance by 5%." },
    [5089] = { name = "Rune of Vendetta", quality = 4, entry = 2530, desc = "Heals you for up to 6% of your maximum health whenever you kill a target that yields experience or honor." },
    [5090] = { name = "Rune of Blade Barrier", quality = 4, entry = 2531, desc = "Whenever your Blood Runes are on cooldown, you gain the Blade Barrier effect, which decreases damage taken by 5% for the next 10 sec." },
    [5091] = { name = "Rune of Outbreak", quality = 4, entry = 2532, desc = "Increases the damage of Plague Strike by 30% and Scourge Strike by 20%." },
    [5092] = { name = "Rune of Torment the Weak", quality = 4, entry = 2533, desc = "Your Frostbolt, Fireball, Frostfire Bolt, Pyroblast, Arcane Missiles, Arcane Blast, and Arcane Barrage abilities deal 9% more damage to snared or slowed targets." },
    [5093] = { name = "Rune of Improved Icy Talons", quality = 4, entry = 2534, desc = "Increases the melee haste of all party and raid members within 100 yds by 20% and your haste by an additional 5%." },
    [5094] = { name = "Rune of Night of the Dead", quality = 4, entry = 2535, desc = "Reduces the cooldown on Raise Dead by 90 sec and the cooldown on Army of the Dead by 4 min.  Also reduces the damage your pet takes from creature area of effect attacks by 90%." },
    [5095] = { name = "Rune of Desecration", quality = 4, entry = 2536, desc = "Your Plague Strikes and Scourge Strikes cause the Desecrated Ground effect.  Targets in the area are slowed by 50% by the grasping arms of the dead while standing on the unholy ground.  Lasts 20 sec." },
    [5096] = { name = "Rune of Kindred Spirits", quality = 4, entry = 2537, desc = "Increases your pet's damage by 20% and you and your pet's movement speed by 10% while your pet is active. This does not stack with other movement speed increasing effects." },
    [5097] = { name = "Rune of T0N0T0", quality = 4, entry = 2538, desc = "Increases the damage done by your Explosive Shot,  Explosive Trap, Black Arrow and Immolation Trap by 12%." },
    [5098] = { name = "Rune of Hunter vs- Wild", quality = 4, entry = 2539, desc = "Increases you and your pet's attack power and ranged attack power equal to 20% of your total Stamina." },
    [5109] = { name = "Rune of Lock and Load", quality = 4, entry = 2540, desc = "You have a 100% chance when you trap a target with Freezing Trap, Freezing Arrow or Frost Trap and a 6% chance when you deal periodic damage with your Immolation Trap, Explosive Trap or Black Arrow to cause your next 2 Arcane Shot or Explosive Shot spells to trigger no cooldown, cost no mana and consume no ammo. This effect has a 22 sec cooldown." },
    [5112] = { name = "Rune of Wrecking Crew", quality = 4, entry = 2541, desc = "Your melee critical hits Enrage you, increasing all damage caused by 10% for 12 sec.  This effect does not stack with Enrage." },
    [5114] = { name = "Rune of Taste for Blood", quality = 4, entry = 2542, desc = "Whenever your Rend ability causes damage, you have a 100% chance of allowing the use of your Overpower ability for 9 sec.  1 charge.  This effect will not occur more than once every 6 sec." },
    [5117] = { name = "Rune of Reaping", quality = 4, entry = 2543, desc = "Whenever you hit with Blood Strike or Pestilence there is a 100% chance that the Blood Rune becomes a Death Rune when it activates.  Death Runes count as a Blood, Frost or Unholy Rune." },
    [5119] = { name = "Rune of Intensify Rage", quality = 4, entry = 2544, desc = "Reduces the cooldown of your Bloodrage, Berserker Rage, Recklessness and Death Wish abilities by 33%." },
    [5121] = { name = "Rune of Unending Fury", quality = 4, entry = 2545, desc = "Increases the damage done by your Slam, Whirlwind and Bloodthirst abilities by 10%." },
    [5122] = { name = "Rune of Renewed Hope", quality = 4, entry = 2546, desc = "Increases the critical effect chance of your Flash Heal, Greater Heal and Penance (Heal) spells by 4% on targets afflicted by the Weakened Soul effect, and you have a 100% chance to reduce all damage taken by 3% for 1 min to all friendly party and raid targets when you cast Power Word: Shield. This effect has a 15 sec cooldown." },
    [5123] = { name = "Rune of Warbringer", quality = 4, entry = 2547, desc = "Your Charge, Intercept and Intervene abilities are now usable while in combat and in any stance.  In addition, your Intervene ability will remove all movement impairing effects." },
    [5124] = { name = "Rune of Genesis", quality = 4, entry = 2548, desc = "Increases the damage and healing done by your periodic spell damage and healing effects by 10%." },
    [5125] = { name = "Rune of Improved Insect Swarm", quality = 4, entry = 2549, desc = "Increases your damage done by your Wrath spell to targets afflicted by your Insect Swarm by 6%, and increases the critical strike chance of your Starfire spell by 3% on targets afflicted by your Moonfire spell." },
    [5126] = { name = "Rune of Nature's Splendor", quality = 4, entry = 2550, desc = "Increases the duration of your Moonfire and Rejuvenation spells by 3 sec, your Regrowth spell by 6 sec, and your Insect Swarm and Lifebloom spells by 2 sec." },
    [5127] = { name = "Rune of Protector of the Pack", quality = 4, entry = 2551, desc = "Increases your attack power by 6% and reduces the damage you take by 12%, while in Bear or Dire Bear Form." },
    [5128] = { name = "Rune of Natural Reaction", quality = 4, entry = 2552, desc = "Increases your dodge while in Bear Form or Dire Bear Form by 6%, and you regenerate 15 rage every time you dodge while in Bear Form or Dire Bear Form." },
    [5129] = { name = "Rune of Master Poisoner", quality = 4, entry = 2553, desc = "Increases the critical hit chance of all attacks made against any target you have poisoned by 3%, reduces the duration of all Poison effects applied to you by 50%, and gives Envenom a 100% chance not to consume Deadly Poison." },
    [5130] = { name = "Rune of Savage Combat", quality = 4, entry = 2554, desc = "Increases your total attack power by 4% and all physical damage caused to enemies you have poisoned is increased by 4%." },
    [5131] = { name = "Rune of Filthy Tricks", quality = 4, entry = 2555, desc = "Reduces the cooldown by 10 sec and energy cost by 10 of your Tricks of the Trade, Distract and Shadowstep abilities and reduces the cooldown of Preparation by 3 min." },
    [5132] = { name = "Rune of Relentless Strikes", quality = 4, entry = 2556, desc = "Your finishing moves have a 20% chance per combo point to restore 25 energy." },
    [5135] = { name = "Rune of Overkill", quality = 4, entry = 2557, desc = "While stealthed, and for 20 seconds after breaking stealth, you regenerate 40% additional energy." },
    [5136] = { name = "Rune of Pandemic", quality = 4, entry = 2558, desc = "Grants the periodic damage from your Corruption and Unstable Affliction spells the ability to critically hit for 100% increased damage, and increases the critical strike damage bonus of your Haunt spell by 100%." },
    [5139] = { name = "Rune of Damage Shield", quality = 4, entry = 2559, desc = "Whenever you take damage from or block a melee attack you cause damage equal to 20% of your block value." },
    [5146] = { name = "Rune of Rime", quality = 4, entry = 2560, desc = "Increases the critical strike chance of your Icy Touch and Obliterate by 15% and casting Obliterate has a 15% chance to reset the cooldown on Howling Blast and cause your next Howling Blast to consume no runes." },
    [5147] = { name = "Rune of Improved Spell Reflection", quality = 4, entry = 2561, desc = "Reduces the chance you'll be hit by spells by 4% and when the ability is used it will reflect the first spell cast against the 4 closest party members within 20 yards." },
    [5148] = { name = "Rune of Ruin", quality = 4, entry = 2562, desc = "Increases the critical strike damage bonus of your Destruction spells and your Imp's Firebolt spell by 100%." },
    [5150] = { name = "Rune of Elemental Fury", quality = 4, entry = 2563, desc = "Increases the critical strike damage bonus of your Searing and Magma Totems and your Fire, Frost, and Nature spells by 100%." },
    [5151] = { name = "Rune of Blood Gorged", quality = 4, entry = 2564, desc = "When you are above 75% health, you deal 10% more damage.  In addition, your attacks ignore up to 10% of your opponent's armor at all times." },
    [5152] = { name = "Rune of Armored to the Teeth", quality = 4, entry = 2565, desc = "Increases your attack power by 3 for every 108 armor value you have." },
    [5153] = { name = "Rune of Vitality", quality = 4, entry = 2566, desc = "Increases your Energy regeneration rate by 40%." },
    [5155] = { name = "Rune of Aggression", quality = 4, entry = 2567, desc = "Increases the damage of your Sinister Strike, Backstab, and Eviscerate abilities by 15%." },
    [5156] = { name = "Rune of Nature's Grace", quality = 4, entry = 2568, desc = "All non-periodic spell criticals have a 100% chance to grace you with a blessing of nature, increasing your spell casting speed by 20% for 4 sec." },
    [5157] = { name = "Rune of Shamanism", quality = 4, entry = 2569, desc = "Your Lightning Bolt and Chain Lightning spells gain an additional 20% and your Lava Burst gains an additional 25% of your bonus damage effects." },
    [5158] = { name = "Rune of Improved Death Strike", quality = 4, entry = 2570, desc = "Increases the damage of your Death Strike by 30%, increases its critical strike chance by 6%, and increases the healing granted by 50%." },
    [5160] = { name = "Rune of Siphon Life", quality = 4, entry = 2571, desc = "When you deal damage with your Corruption spell, you are instantly healed for 40% of the damage done. In addition, the damage done by your Corruption, Seed of Corruption and Unstable Affliction damage over time effects is increased by 4%." },
    [5163] = { name = "Rune of Nemesis", quality = 4, entry = 2572, desc = "Reduces the cooldown of your Demonic Empowerment, Metamorphosis, and Fel Domination spells by 30%." },
    [5167] = { name = "Rune of Decimation", quality = 4, entry = 2573, desc = "When you Shadowbolt, Incinerate or Soul Fire a target that is at or below 35% health, the cast time of your Soul Fire spell is reduced by 40% for 10 sec. Soul Fires cast under the effect of Decimation cost no shard." },
    [5168] = { name = "Rune of Pyroclasm", quality = 4, entry = 2574, desc = "When you critically strike with Searing Pain or Conflagrate, your Fire and Shadow spell damage is increased by 6% for 10 sec." },
    [5170] = { name = "Rune of Molten Skin", quality = 4, entry = 2575, desc = "Reduces all damage taken by 6%." },
    [5173] = { name = "Rune of Booming Echoes", quality = 4, entry = 2576, desc = "Reduces the cooldown of your Flame Shock and Frost Shock spells by an additional 2 sec., and increases the direct damage done by your Flame Shock and Frost Shock spells by an additional 20%." },
    [5175] = { name = "Rune of Frozen Power", quality = 4, entry = 2577, desc = "Increases the damage done by your Lightning Bolt, Chain Lightning, Lava Lash and Shock spells by 10% on targets afflicted by your Frostbrand Attack effect, and your Frost Shock has a 100% chance to root the target in ice for 5 sec. when used on targets at or further than 15 yards from you." },
    [5181] = { name = "Rune of Improved Barkskin", quality = 4, entry = 2578, desc = "Grants 160% additional armor contribution from cloth and leather items while in Travel Form or while not shapeshifted, increases the damage reduction granted by your Barkskin spell by 10% and reduces the chance your Barkskin is dispelled by 70%." },
    [5182] = { name = "Rune of Trap Mastery", quality = 4, entry = 2579, desc = "Frost Trap and Freezing Trap - Increases the duration by 30%." },
    [5183] = { name = "Rune of Primal Gore", quality = 4, entry = 2580, desc = "Grants the periodic damage from your Lacerate and Rip abilities the ability to critically hit." },
    [5184] = { name = "Rune of Improved Flash Heal", quality = 4, entry = 2581, desc = "Reduces the mana cost of your Flash Heal by 15%, and increases the critical effect chance of your Flash Heal by 15% on friendly targets at or below 50% health." },
    [5190] = { name = "Rune of Empowered Renew", quality = 4, entry = 2582, desc = "Your Renew spell gains an additional 25% of your bonus healing effects, and your Renew will instantly heal the target for 25% of the total periodic effect." },
    [5191] = { name = "Rune of Soul Warding", quality = 4, entry = 2583, desc = "Reduces the cooldown of your Power Word: Shield ability by 4 sec, and reduces the mana cost of your Power Word: Shield by 15%." },
    [5192] = { name = "Rune of Improved Devouring Plague", quality = 4, entry = 2584, desc = "Increases the periodic damage done by your Devouring Plague by 15%, and when you cast Devouring Plague you instantly deal damage equal to 30% of its total periodic effect." },
    [5193] = { name = "Rune of Divinity", quality = 4, entry = 2585, desc = "Increases all healing done by you and all healing effects on you by 5%." },
    [5194] = { name = "Rune of Serendipity", quality = 4, entry = 2586, desc = "When you heal with Binding Heal or Flash Heal, the cast time of your next Greater Heal or Prayer of Healing spell is reduced by 15%. Stacks up to 3 times. Lasts 20 sec." },
    [5197] = { name = "Rune of Body and Soul", quality = 4, entry = 2587, desc = "When you cast Power Word: Shield, you increase the target's movement speed by 60% for 4 sec, and you have a 100% chance when you cast Abolish Disease on yourself to also cleanse 1 poison effect in addition to diseases." },
    [5198] = { name = "Rune of Fiery Payback", quality = 4, entry = 2588, desc = "When below 35% health all damage taken is reduced by 20% and your Pyroblast spell's cast time is reduced by 3.5.1 secs while the cooldown is increased by 5 secs.  In addition, melee and ranged attacks made against you have a 10% chance to disarm your attacker's main hand and ranged weapons." },
    [5199] = { name = "Rune of Juggernaut", quality = 4, entry = 2589, desc = "Your Charge ability is now usable while in combat, but the cooldown on Charge is increased by 5 sec. Following a Charge, your next Slam or Mortal Strike has an additional 25% chance to critically hit if used within 10 sec." },
    [5203] = { name = "Rune of Threat of Thassarian", quality = 4, entry = 2590, desc = "When dual-wielding, your Death Strikes, Obliterates, Plague Strikes, Rune Strikes, Blood Strikes and Frost Strikes have a 100% chance to also deal damage with your offhand weapon." },
    [5204] = { name = "Rune of Desolation", quality = 4, entry = 2591, desc = "Your Blood Strikes cause you to deal 5% additional damage with all attacks for the next 20 sec." },
    [54810] = { name = "Rune of Frenzied Regeneration", quality = 3, entry = 1547, desc = "While Frenzied Regeneration is active, healing effects on you are 20% more powerful." },
    [54811] = { name = "Rune of Maul", quality = 3, entry = 1548, desc = "Your Maul ability now hits 1 additional target." },
    [54813] = { name = "Rune of Mangle", quality = 3, entry = 1549, desc = "Increases the damage done by Mangle by 10%." },
    [54815] = { name = "Rune of Shred", quality = 3, entry = 1550, desc = "Each time you Shred, the duration of your Rip on the target is extended 2 sec, up to a maximum of 6 sec." },
    [54818] = { name = "Rune of Rip", quality = 3, entry = 1551, desc = "Increases the duration of your Rip ability by 4 sec." },
    [54821] = { name = "Rune of Rake", quality = 3, entry = 1552, desc = "Your Rake ability prevents targets from fleeing." },
    [54824] = { name = "Rune of Swiftmend", quality = 3, entry = 1553, desc = "Your Swiftmend ability no longer consumes a Rejuvenation or Regrowth effect from the target." },
    [54832] = { name = "Rune of Innervate", quality = 3, entry = 1554, desc = "Innervate now grants the caster 45% of their base mana pool over 10 sec in addition to the normal effects of Innervate." },
    [54733] = { name = "Rune of Rebirth", quality = 3, entry = 1555, desc = "Players resurrected by Rebirth are returned to life with 100% health." },
    [54743] = { name = "Rune of Regrowth", quality = 3, entry = 1556, desc = "Increases the healing of your Regrowth spell by 20% if your Regrowth effect is still active on the target." },
    [54754] = { name = "Rune of Rejuvenation", quality = 3, entry = 1557, desc = "While your Rejuvenation targets are below 50% health, you will heal them for an additional 50% health." },
    [54825] = { name = "Rune of Healing Touch", quality = 3, entry = 1558, desc = "Decreases the cast time of Healing Touch by 1.5.1 sec, the mana cost by 25%, and the amount healed by 50%." },
    [54826] = { name = "Rune of Lifebloom", quality = 3, entry = 1559, desc = "Increases the duration of Lifebloom by 1 sec." },
    [54845] = { name = "Rune of Starfire", quality = 3, entry = 1560, desc = "Your Starfire ability increases the duration of your Moonfire effect on the target by 3 sec, up to a maximum of 9 additional seconds." },
    [54830] = { name = "Rune of Insect Swarm", quality = 3, entry = 1561, desc = "Increases the damage of your Insect Swarm ability by 30%, but it no longer affects your victim's chance to hit." },
    [54831] = { name = "Rune of Hurricane", quality = 3, entry = 1562, desc = "Your Hurricane ability now also slows the movement speed of its victims by 20%." },
    [54828] = { name = "Rune of Starfall", quality = 3, entry = 1563, desc = "Reduces the cooldown of Starfall by 30 sec." },
    [54756] = { name = "Rune of Wrath", quality = 3, entry = 1564, desc = "Reduces the pushback suffered from damaging attacks while casting your Wrath spell by 50%." },
    [54829] = { name = "Rune of Moonfire", quality = 3, entry = 1565, desc = "Increases the periodic damage of your Moonfire ability by 75%, but initial damage is decreased by 90%." },
    [54760] = { name = "Rune of Entangling Roots", quality = 3, entry = 1566, desc = "Increases the damage your Entangling Roots victims can take before the Entangling Roots automatically breaks by 20%." },
    [54922] = { name = "Rune of Judgement", quality = 3, entry = 1567, desc = "Your Judgements deal 10% more damage." },
    [54925] = { name = "Rune of Seal of Command", quality = 3, entry = 1568, desc = "You gain 8% of your base mana each time you use a Judgement with Seal of Command active." },
    [54923] = { name = "Rune of Hammer of Justice", quality = 3, entry = 1569, desc = "Increases your Hammer of Justice range by 5 yards." },
    [54924] = { name = "Rune of Spiritual Attunement", quality = 3, entry = 1570, desc = "Increases the amount of mana gained from your Spiritual Attunement spell by an additional 2%." },
    [54926] = { name = "Rune of Hammer of Wrath", quality = 3, entry = 1571, desc = "Reduces the mana cost of Hammer of Wrath by 100%." },
    [54927] = { name = "Rune of Crusader Strike", quality = 3, entry = 1572, desc = "Reduces the mana cost of your Crusader Strike ability by 20%." },
    [54928] = { name = "Rune of Consecration", quality = 3, entry = 1573, desc = "Increases the duration and cooldown of Consecration by 2 sec." },
    [54929] = { name = "Rune of Righteous Defense", quality = 3, entry = 1574, desc = "Increases the chance for your Righteous Defense and Hand of Reckoning abilities to work successfully by 8% on each target." },
    [54930] = { name = "Rune of Avenger's Shield", quality = 3, entry = 1575, desc = "Your Avenger's Shield hits 2 fewer targets, but for 100% more damage." },
    [54931] = { name = "Rune of Turn Evil", quality = 3, entry = 1576, desc = "Reduces the casting time of your Turn Evil spell by 100%, but increases the cooldown by 8 sec." },
    [54934] = { name = "Rune of Exorcism", quality = 3, entry = 1577, desc = "Increases damage done by Exorcism by 20%." },
    [54935] = { name = "Rune of Cleansing", quality = 3, entry = 1578, desc = "Reduces the mana cost of your Cleanse and Purify spells by 20%." },
    [54936] = { name = "Rune of Flash of Light", quality = 3, entry = 1579, desc = "Your Flash of Light has an additional 5% critical strike chance." },
    [54937] = { name = "Rune of Holy Light", quality = 3, entry = 1580, desc = "Your Holy Light grants 10% of its heal amount to up to 5 friendly targets within 8 yards of the initial target." },
    [54938] = { name = "Rune of Avenging Wrath", quality = 3, entry = 1581, desc = "Reduces the cooldown of your Hammer of Wrath spell by 50% while Avenging Wrath is active." },
    [54939] = { name = "Rune of Divinity", quality = 3, entry = 1582, desc = "Your Lay on Hands grants twice as much mana as normal and also grants you as much mana as it grants your target." },
    [54940] = { name = "Rune of Seal of Wisdom", quality = 3, entry = 1583, desc = "While Seal of Wisdom is active, the cost of your healing spells is reduced by 5%." },
    [54943] = { name = "Rune of Seal of Light", quality = 3, entry = 1584, desc = "While Seal of Light is active, the effect of your healing spells is increased by 5%." },
    [55436] = { name = "Rune of Water Mastery", quality = 3, entry = 1585, desc = "Increases the passive mana regeneration of your Water Shield spell by 30%." },
    [55437] = { name = "Rune of Chain Heal", quality = 3, entry = 1586, desc = "Your Chain Heal heals 1 additional target." },
    [55449] = { name = "Rune of Chain Lightning", quality = 3, entry = 1587, desc = "Your Chain Lightning strikes 1 additional target." },
    [55454] = { name = "Rune of Lava", quality = 3, entry = 1588, desc = "Your Lava Burst spell gains an additional 10% of your spellpower." },
    [55442] = { name = "Rune of Shocking", quality = 3, entry = 1589, desc = "Reduces the global cooldown triggered by your shock spells to 1 sec." },
    [55439] = { name = "Rune of Earthliving Weapon", quality = 3, entry = 1590, desc = "Increases the chance for your Earthliving weapon to trigger by 5%." },
    [55455] = { name = "Rune of Fire Elemental Totem", quality = 3, entry = 1591, desc = "Reduces the cooldown of your Fire Elemental Totem by 5 min." },
    [55450] = { name = "Rune of Fire Nova", quality = 3, entry = 1592, desc = "Reduces the cooldown of your Fire Nova spell by 3 seconds." },
