-- Reverse lookup by lowercase name (with and without prefixes)
GH.RuneDataByName = {}
for sid, data in pairs(GH.RuneData) do
    if data.name then
        local lower = string.lower(data.name)
        GH.RuneDataByName[lower] = sid
        local stripped = string.gsub(lower, "^rune of%s+", "")
        if stripped ~= lower then
            GH.RuneDataByName[stripped] = sid
        end
        local strippedThe = string.gsub(stripped, "^the%s+", "")
        if strippedThe ~= stripped then
            GH.RuneDataByName[strippedThe] = sid
        end
    end
end
